@WebServlet("/safe-counter")
public class SafeCounterServlet extends HttpServlet {
    // Use AtomicInteger for thread-safe counting without manual locks
    private java.util.concurrent.atomic.AtomicInteger visitCount = new java.util.concurrent.atomic.AtomicInteger(0);

    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        int currentVisits = visitCount.incrementAndGet(); // Thread-safe atomic increment
        response.setContentType("text/html");
        PrintWriter out = response.getWriter();
        out.println("<h3>Total visits (Thread-safe): " + currentVisits + "</h3>");
    }
}

